#include <stdio.h>

#define MAXN 16

/* out 是 1..n 的一个排列，判断它是否为合法出栈序列 */
int IsValidPop(const int *out, int n)
{
    int st[MAXN], top = 0, next = 1, i;
    for (i = 0; i < n; i++) {
        while (top == 0 || st[top - 1] != out[i]) {
            if (next > n) return 0;        /* 没有元素可再入栈 */
            st[top++] = next++;
        }
        top--;                             /* 弹出栈顶 */
    }
    return 1;
}

int main(void)
{
    int s1[3] = {3, 2, 1};
    int s2[3] = {3, 1, 2};
    int s3[3] = {1, 3, 2};
    int s4[4] = {4, 2, 3, 1};
    int s5[4] = {4, 1, 3, 2};

    printf("3 2 1 -> %s\n", IsValidPop(s1, 3) ? "合法" : "非法");
    printf("3 1 2 -> %s\n", IsValidPop(s2, 3) ? "合法" : "非法");
    printf("1 3 2 -> %s\n", IsValidPop(s3, 3) ? "合法" : "非法");
    printf("4 2 3 1 -> %s\n", IsValidPop(s4, 4) ? "合法" : "非法");
    printf("4 1 3 2 -> %s\n", IsValidPop(s5, 4) ? "合法" : "非法");
    return 0;
}

#include <stdio.h>

#define N 3

static int st[N + 1], top = 0;
static int out[N], len = 0;
static int pushed = 0;
static int cnt = 0;

void dfs(void)
{
    int i, v;
    if (len == N) {                       /* N 个元素全部出栈 */
        cnt++;
        printf("%d: ", cnt);
        for (i = 0; i < N; i++) printf("%d", out[i]);
        printf("\n");
        return;
    }
    if (pushed < N) {                     /* 分支一：入栈 */
        st[top++] = ++pushed;
        dfs();
        top--; pushed--;                  /* 回溯 */
    }
    if (top > 0) {                        /* 分支二：出栈 */
        v = st[--top];
        out[len++] = v;
        dfs();
        len--; st[top++] = v;             /* 回溯 */
    }
}

int main(void)
{
    dfs();
    printf("n=%d 共 %d 种出栈序列 = C(2n,n)/(n+1)\n", N, cnt);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define STACK_INIT_SIZE 4
#define STACKINCREMENT  2

typedef int ElemType;
typedef struct {
    ElemType *base;
    ElemType *top;
    int       stacksize;
} SqStack;

int InitStack(SqStack *S)
{
    S->base = (ElemType *)malloc(STACK_INIT_SIZE * sizeof(ElemType));
    if (S->base == NULL) return 0;
    S->top = S->base;                  /* 空栈 */
    S->stacksize = STACK_INIT_SIZE;
    return 1;
}

int StackEmpty(const SqStack *S) { return S->top == S->base; }
int StackLen  (const SqStack *S) { return (int)(S->top - S->base); }

int Push(SqStack *S, ElemType e)
{
    ElemType *newbase;
    if (StackLen(S) >= S->stacksize) {         /* 栈满，扩容 */
        newbase = (ElemType *)realloc(S->base,
                    (size_t)(S->stacksize + STACKINCREMENT) * sizeof(ElemType));
        if (newbase == NULL) return 0;
        S->base = newbase;                     /* base 可能已搬家 */
        S->top  = S->base + S->stacksize;      /* top 必须重算 */
        S->stacksize += STACKINCREMENT;
        printf("  [realloc -> stacksize=%d]\n", S->stacksize);
    }
    *S->top++ = e;                             /* 先赋值，后上移 */
    return 1;
}

int Pop(SqStack *S, ElemType *e)
{
    if (StackEmpty(S)) return 0;
    *e = *--S->top;                            /* 先下移，后取值 */
    return 1;
}

int main(void)
{
    SqStack S;
    ElemType e = 0;
    int i;
    if (!InitStack(&S)) { printf("malloc failed\n"); return 1; }

    for (i = 1; i <= 7; i++) { Push(&S, i * 10); printf("push %d len=%d\n", i*10, StackLen(&S)); }
    printf("stacksize=%d base!=NULL %d\n", S.stacksize, S.base != NULL);
    while (!StackEmpty(&S)) { Pop(&S, &e); printf("pop %d ", e); }
    printf("\nempty=%d\n", StackEmpty(&S));
    printf("pop on empty stack -> %s\n", Pop(&S, &e) ? "ok" : "failed");
    free(S.base);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAXSIZE 6
typedef int ElemType;

typedef struct SNode { ElemType data; struct SNode *next; } SNode, *LinkStack;

int PushL(LinkStack *top, ElemType e)     /* 链栈入栈：头插 */
{
    SNode *s = (SNode *)malloc(sizeof(SNode));
    if (s == NULL) return 0;
    s->data = e;
    s->next = *top;
    *top = s;
    return 1;
}

int PopL(LinkStack *top, ElemType *e)     /* 链栈出栈：头删 */
{
    SNode *p = *top;
    if (p == NULL) return 0;
    *e = p->data;
    *top = p->next;
    free(p);
    return 1;
}

/* 两栈共享 base[0..MAXSIZE-1]：top1 从左往右，top2 从右往左 */
static ElemType base[MAXSIZE];
static int top1 = -1, top2 = MAXSIZE;

int Push1(ElemType e) { if (top1 + 1 == top2) return 0; base[++top1] = e; return 1; }
int Push2(ElemType e) { if (top1 + 1 == top2) return 0; base[--top2] = e; return 1; }

int main(void)
{
    LinkStack top = NULL;
    ElemType e = 0;
    int i;

    for (i = 1; i <= 4; i++) PushL(&top, i * 100);
    printf("链栈出栈(应为逆序):");
    while (PopL(&top, &e)) printf(" %d", e);
    printf("\n链栈已空 top==NULL ? %d\n", top == NULL);

    for (i = 1; i <= 3; i++) printf("Push1(%d)=%s ", i, Push1(i) ? "ok" : "full");
    printf("\n");
    for (i = 1; i <= 3; i++) printf("Push2(%d)=%s ", i, Push2(i) ? "ok" : "full");
    printf("\nPush1(4)=%s (top1=%d top2=%d 已相遇)\n",
           Push1(4) ? "ok" : "full", top1, top2);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define MAXQSIZE 6          /* 少用一个单元，实际容量 5 */

typedef int ElemType;
typedef struct {
    ElemType *base;
    int front;
    int rear;
} SqQueue;

int InitQueue(SqQueue *Q)
{
    Q->base = (ElemType *)malloc(MAXQSIZE * sizeof(ElemType));
    if (Q->base == NULL) return 0;
    Q->front = Q->rear = 0;
    return 1;
}

int QueueEmpty (const SqQueue *Q) { return Q->front == Q->rear; }
int QueueFull  (const SqQueue *Q) { return (Q->rear + 1) % MAXQSIZE == Q->front; }
int QueueLength(const SqQueue *Q) { return (Q->rear - Q->front + MAXQSIZE) % MAXQSIZE; }

int EnQueue(SqQueue *Q, ElemType e)
{
    if (QueueFull(Q)) return 0;
    Q->base[Q->rear] = e;
    Q->rear = (Q->rear + 1) % MAXQSIZE;
    return 1;
}

int DeQueue(SqQueue *Q, ElemType *e)
{
    if (QueueEmpty(Q)) return 0;
    *e = Q->base[Q->front];
    Q->front = (Q->front + 1) % MAXQSIZE;
    return 1;
}

int main(void)
{
    SqQueue Q;
    ElemType e = 0;
    int v = 10, i;
    if (!InitQueue(&Q)) { printf("malloc failed\n"); return 1; }

    for (i = 0; i < 5; i++) {
        EnQueue(&Q, v); printf("入队 %2d  rear=%d\n", v, Q.rear); v += 10;
    }
    printf("入队 %2d -> %s\n", v, EnQueue(&Q, v) ? "ok" : "队满(少用一个单元)");
    printf("length=%d front=%d rear=%d\n", QueueLength(&Q), Q.front, Q.rear);

    for (i = 0; i < 3; i++) { DeQueue(&Q, &e); printf("出队 %2d  front=%d\n", e, Q.front); }
    EnQueue(&Q, v); printf("入队 %2d  rear=%d  <- rear 回绕到 0\n", v, Q.rear); v += 10;
    EnQueue(&Q, v); printf("入队 %2d  rear=%d\n", v, Q.rear); v += 10;
    printf("length=%d front=%d rear=%d\n", QueueLength(&Q), Q.front, Q.rear);

    printf("全部出队:");
    while (!QueueEmpty(&Q)) { DeQueue(&Q, &e); printf(" %d", e); }
    printf("\nempty=%d\n", QueueEmpty(&Q));
    free(Q.base);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef char ElemType;
typedef struct QNode { ElemType data; struct QNode *next; } QNode, *QueuePtr;
typedef struct { QueuePtr front, rear; } LinkQueue;

int InitQueue(LinkQueue *Q)
{
    Q->front = Q->rear = (QueuePtr)malloc(sizeof(QNode));   /* 头结点 */
    if (Q->front == NULL) return 0;
    Q->front->next = NULL;
    return 1;
}

int EnQueue(LinkQueue *Q, ElemType e)
{
    QueuePtr s = (QueuePtr)malloc(sizeof(QNode));
    if (s == NULL) return 0;
    s->data = e; s->next = NULL;
    Q->rear->next = s;
    Q->rear = s;
    return 1;
}

int DeQueue(LinkQueue *Q, ElemType *e)
{
    QueuePtr p;
    if (Q->front == Q->rear) return 0;        /* 队空 */
    p = Q->front->next;                       /* 队头元素结点 */
    *e = p->data;
    Q->front->next = p->next;
    if (Q->rear == p) Q->rear = Q->front;     /* ★ 删的是最后一个元素 */
    free(p);
    return 1;
}

int main(void)
{
    LinkQueue Q;
    ElemType e = 0;
    QueuePtr p;
    if (!InitQueue(&Q)) { printf("malloc failed\n"); return 1; }

    EnQueue(&Q, 'a'); EnQueue(&Q, 'b'); EnQueue(&Q, 'c');
    printf("队列:");
    for (p = Q.front->next; p != NULL; p = p->next) printf(" %c", p->data);
    printf("\n");
    DeQueue(&Q, &e); printf("出队 %c\n", e);
    DeQueue(&Q, &e); printf("出队 %c\n", e);
    DeQueue(&Q, &e); printf("出队 %c  <- 这是最后一个元素\n", e);
    printf("rear 已修正: front==rear ? %d\n", Q.front == Q.rear);
    printf("再出队 -> %s\n", DeQueue(&Q, &e) ? "ok" : "队空，失败");
    EnQueue(&Q, 'z');
    printf("重新入队 z -> front==rear ? %d, data=%c\n",
           Q.front == Q.rear, Q.rear->data);
    free(Q.front);
    return 0;
}

#include <stdio.h>

#define STACKSIZE 64

static void convert(int n, int d)
{
    int st[STACKSIZE], top = 0, i;
    printf("%d 的 %d 进制 = ", n, d);
    if (n == 0) st[top++] = 0;             /* 0 的特殊情况 */
    while (n > 0) { st[top++] = n % d; n /= d; }   /* 余数入栈 */
    for (i = top - 1; i >= 0; i--) {       /* 逆序出栈 */
        if (st[i] < 10) printf("%d", st[i]);
        else            printf("%c", 'A' + st[i] - 10);
    }
    printf("\n");
}

int main(void)
{
    convert(1348, 8);
    convert(255, 16);
    convert(0, 8);
    convert(10, 2);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXOP 32

int main(void)
{
    const char *expr = "6 2 3 + * 4 -";
    double st[MAXOP];
    int top = 0;
    const char *p = expr;
    char tok[16];

    printf("后缀表达式: %s\n", expr);
    while (*p != '\0') {
        while (*p == ' ') p++;                     /* 跳过空白 */
        if (*p == '\0') break;
        {
            int i = 0;
            while (*p != '\0' && *p != ' ') tok[i++] = *p++;
            tok[i] = '\0';                         /* 取出一个单词 */
        }
        if (strlen(tok) == 1 && strchr("+-*/", tok[0]) != NULL) {
            double b = st[--top];                  /* 先弹出的是右操作数 */
            double a = st[--top];
            switch (tok[0]) {
            case '+': st[top++] = a + b; break;
            case '-': st[top++] = a - b; break;
            case '*': st[top++] = a * b; break;
            default : st[top++] = a / b; break;
            }
            printf("  %g %s %g = %g\n", a, tok, b, st[top - 1]);
        } else {
            st[top++] = atof(tok);
            printf("  push %s\n", tok);
        }
    }
    printf("结果 = %g\n", st[--top]);
    return 0;
}

#include <stdio.h>

#define MAXSIZE 4
typedef int DataType;

/* 约定 A：top 指向栈顶元素，空栈 top == -1 */
typedef struct {
    DataType data[MAXSIZE];
    int top;
} StackA;

void stackAInit(StackA *s)
{
    s->top = -1;
}

int stackAPush(StackA *s, DataType x)
{
    if (s->top == MAXSIZE - 1) {
        return 1;                      /* 上溢 */
    }
    s->data[++s->top] = x;             /* 先加后用 */
    return 0;
}

int stackAPop(StackA *s, DataType *x)
{
    if (s->top == -1) {
        return 1;                      /* 下溢 */
    }
    *x = s->data[s->top--];            /* 先用后减 */
    return 0;
}

int stackACount(const StackA *s)
{
    return s->top + 1;                 /* 约定 A 元素个数 = top + 1 */
}

/* 约定 B：top 指向下一个可写空位，空栈 top == 0 */
typedef struct {
    DataType data[MAXSIZE];
    int top;
} StackB;

void stackBInit(StackB *s)
{
    s->top = 0;
}

int stackBPush(StackB *s, DataType x)
{
    if (s->top == MAXSIZE) {
        return 1;
    }
    s->data[s->top++] = x;             /* 后用再加 */
    return 0;
}

int stackBPop(StackB *s, DataType *x)
{
    if (s->top == 0) {
        return 1;
    }
    *x = s->data[--s->top];            /* 先减后用 */
    return 0;
}

int stackBCount(const StackB *s)
{
    return s->top;                     /* 约定 B 元素个数 = top */
}

int main(void)
{
    StackA a;
    StackB b;
    DataType vals[6] = { 10, 20, 30, 40, 50, 60 };
    DataType x;
    int i;

    stackAInit(&a);
    stackBInit(&b);
    printf("初始：A.top=%d A个数=%d | B.top=%d B个数=%d\n",
           a.top, stackACount(&a), b.top, stackBCount(&b));

    for (i = 0; i < 6; i++) {
        printf("push %d → A返回%d B返回%d\n",
               vals[i], stackAPush(&a, vals[i]), stackBPush(&b, vals[i]));
    }
    printf("满栈：A个数=%d B个数=%d\n", stackACount(&a), stackBCount(&b));

    for (i = 0; i < 4; i++) {          /* 弹满 4 次才真正清空 */
        stackAPop(&a, &x);
        printf("A出栈 %d，剩余 %d 个\n", x, stackACount(&a));
    }
    for (i = 0; i < 4; i++) {
        stackBPop(&b, &x);
        printf("B出栈 %d，剩余 %d 个\n", x, stackBCount(&b));
    }
    printf("清空后再 pop：A返回%d B返回%d（均为下溢）\n",
           stackAPop(&a, &x), stackBPop(&b, &x));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct StackNode {
    int data;
    struct StackNode *next;
} StackNode;

/* 入栈：插在表头。返回 1 表示分配失败 */
int push(StackNode **top, int x)
{
    StackNode *p = (StackNode *)malloc(sizeof(StackNode));

    if (p == NULL) {
        return 1;
    }
    p->data = x;
    p->next = *top;                /* 先接旧栈顶 */
    *top = p;                      /* 再当新栈顶 */
    return 0;
}

/* 出栈：摘下表头，数据由 *x 带出。返回 1 表示下溢 */
int pop(StackNode **top, int *x)
{
    StackNode *p;

    if (*top == NULL) {
        return 1;
    }
    *x = (*top)->data;             /* ① 先取数据 */
    p = *top;                      /* ② 再存指针 */
    *top = (*top)->next;           /* ③ 改栈顶 */
    free(p);                       /* ④ 最后释放 */
    return 0;
}

int stackEmpty(const StackNode *top)
{
    return top == NULL;
}

int stackSize(const StackNode *top)
{
    int n = 0;
    const StackNode *p;

    for (p = top; p != NULL; p = p->next) {
        n++;
    }
    return n;
}

/* 进制转换：除基取余，余数入栈，最后依次出栈即为结果 */
void convert(int n, int base)
{
    StackNode *top = NULL;
    int d;

    if (n == 0) {
        printf("%d 的 %d 进制 = 0\n", n, base);
        return;
    }
    while (n > 0) {
        if (push(&top, n % base) != 0) {
            printf("分配失败\n");
            return;
        }
        n = n / base;
    }
    printf("转换结果（栈深 %d）=", stackSize(top));
    while (!stackEmpty(top)) {
        pop(&top, &d);
        printf("%c", d < 10 ? (char)('0' + d) : (char)('A' + d - 10));
    }
    printf("\n");
}

int main(void)
{
    StackNode *top = NULL;
    int vals[4] = { 5, 15, 25, 35 };
    int x, i;

    for (i = 0; i < 4; i++) {
        push(&top, vals[i]);
    }
    printf("压入 5 15 25 35 后栈深 %d，是否为空 %d\n", stackSize(top), stackEmpty(top));

    while (!stackEmpty(top)) {
        pop(&top, &x);
        printf("出栈 %d，剩余 %d\n", x, stackSize(top));
    }
    printf("空栈再 pop 返回 %d（下溢）\n", pop(&top, &x));

    convert(1348, 8);
    convert(255, 16);
    convert(0, 2);
    return 0;
}

#include <stdio.h>

#define MAXSIZE 8
typedef int DataType;

typedef struct {
    DataType data[MAXSIZE];
    int top0;                 /* 栈 0：从左向右生长 */
    int top1;                 /* 栈 1：从右向左生长 */
} DStack;

void dsInit(DStack *s)
{
    s->top0 = -1;
    s->top1 = MAXSIZE;
}

int dsFull(const DStack *s)
{
    return s->top0 + 1 == s->top1;    /* 两个栈顶相邻即整体满 */
}

int dsPush(DStack *s, int which, DataType x)
{
    if (dsFull(s)) {
        return 1;                      /* 上溢 */
    }
    if (which == 0) {
        s->data[++s->top0] = x;
    } else {
        s->data[--s->top1] = x;
    }
    return 0;
}

int dsPop(DStack *s, int which, DataType *x)
{
    if (which == 0) {
        if (s->top0 == -1) {
            return 1;                  /* 栈 0 下溢 */
        }
        *x = s->data[s->top0--];
    } else {
        if (s->top1 == MAXSIZE) {
            return 1;                  /* 栈 1 下溢 */
        }
        *x = s->data[s->top1++];       /* 栈 1 向左生长，出栈往右退 */
    }
    return 0;
}

int dsCount(const DStack *s, int which)
{
    return which == 0 ? s->top0 + 1 : MAXSIZE - s->top1;
}

static void showLayout(const DStack *s)
{
    int i;

    printf("数组占用:");
    for (i = 0; i < MAXSIZE; i++) {
        if (i <= s->top0) {
            printf(" [%d]=%d(栈0)", i, s->data[i]);
        } else if (i >= s->top1) {
            printf(" [%d]=%d(栈1)", i, s->data[i]);
        } else {
            printf(" [%d]=空", i);
        }
    }
    printf("\n");
}

int main(void)
{
    DStack s;
    DataType x;
    int i, r;

    dsInit(&s);
    printf("初始 top0=%d top1=%d，栈0个数=%d 栈1个数=%d\n",
           s.top0, s.top1, dsCount(&s, 0), dsCount(&s, 1));

    /* 交替压入：栈 0 放 10 20 30 40 50，栈 1 放 1 2 3 */
    for (i = 0; i < 5; i++) {
        r = dsPush(&s, 0, (i + 1) * 10);
        printf("栈0 push %d → %d\n", (i + 1) * 10, r);
        if (i < 3) {
            r = dsPush(&s, 1, i + 1);
            printf("栈1 push %d → %d\n", i + 1, r);
        }
    }
    printf("此时 top0=%d top1=%d，已满=%d\n", s.top0, s.top1, dsFull(&s));
    showLayout(&s);

    printf("再往栈0 push 60 → %d（上溢）\n", dsPush(&s, 0, 60));
    printf("再往栈1 push 4  → %d（上溢）\n", dsPush(&s, 1, 4));

    for (i = 0; i < 3; i++) {
        dsPop(&s, 1, &x);
        printf("栈1 pop %d，剩余 %d\n", x, dsCount(&s, 1));
    }
    printf("栈1 腾空后往栈0 push 60 → %d（借用空间成功）\n", dsPush(&s, 0, 60));
    printf("最终 top0=%d top1=%d，栈0个数=%d\n", s.top0, s.top1, dsCount(&s, 0));

    while (dsPop(&s, 0, &x) == 0) {
        printf("栈0 pop %d\n", x);
    }
    printf("栈0 空后再 pop 返回 %d（下溢）\n", dsPop(&s, 0, &x));
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXSIZE 100

typedef struct {
    char ch[MAXSIZE];
    int pos[MAXSIZE];          /* 记录每个左括号在原串中的下标，便于报告位置 */
    int top;
} BracketStack;

static int isLeft(char c)
{
    return c == '(' || c == '[' || c == '{';
}

static int isRight(char c)
{
    return c == ')' || c == ']' || c == '}';
}

static int matchPair(char left, char right)
{
    return (left == '(' && right == ')') ||
           (left == '[' && right == ']') ||
           (left == '{' && right == '}');
}

/* 返回 0 匹配；1 右括号多余；2 类型不匹配；3 左括号多余 */
int checkBrackets(const char *s, int *errPos)
{
    BracketStack st;
    int i, len = (int)strlen(s);

    st.top = -1;
    *errPos = -1;
    for (i = 0; i < len; i++) {
        if (isLeft(s[i])) {
            if (st.top == MAXSIZE - 1) {
                *errPos = i;
                return 1;                      /* 栈本身溢出，按多余处理 */
            }
            st.ch[++st.top] = s[i];
            st.pos[st.top] = i;
        } else if (isRight(s[i])) {
            if (st.top == -1) {
                *errPos = i;
                return 1;                      /* 右括号多余 */
            }
            if (!matchPair(st.ch[st.top], s[i])) {
                *errPos = st.pos[st.top];
                return 2;                      /* 类型不匹配，报告左括号位置 */
            }
            st.top--;
        }
        /* 其他字符直接跳过，不入栈 */
    }
    if (st.top != -1) {
        *errPos = st.pos[st.top];
        return 3;                              /* 左括号多余 */
    }
    return 0;
}

int main(void)
{
    const char *cases[6] = {
        "a[b{c(1+2)*3}]+d",
        "int f(int x){ return (x>0)? x : -x; }",
        "a[b(c]d)",
        "a)b(c",
        "a{b(c}d)",
        "((1+2)*3"
    };
    const char *reason[4] = { "匹配", "右括号多余", "类型不匹配", "左括号多余" };
    int i, r, pos;

    for (i = 0; i < 6; i++) {
        r = checkBrackets(cases[i], &pos);
        printf("用例%d [%s]\n  → %s", i + 1, cases[i], reason[r]);
        if (r != 0) {
            printf("（位置 %d，字符 '%c'）", pos, cases[i][pos]);
        }
        printf("\n");
    }
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAXSIZE 100

/* 栈内优先级：左括号在栈内最低，只有右括号能把它弹出 */
static int inStackPriority(char op)
{
    switch (op) {
    case '(': return 0;
    case '+':
    case '-': return 1;
    case '*':
    case '/':
    case '%': return 2;
    default:  return -1;
    }
}

/* 栈外优先级：左括号最高，迫使任何运算符都入栈 */
static int outStackPriority(char op)
{
    switch (op) {
    case '(': return 3;
    case '+':
    case '-': return 1;
    case '*':
    case '/':
    case '%': return 2;
    default:  return -1;
    }
}

static int isOperand(char c)
{
    return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

/* 中缀转后缀；out 需足够长。返回 0 成功，1 括号失配 */
int infixToPostfix(const char *infix, char *out)
{
    char stack[MAXSIZE];
    int top = -1, k = 0, i, len = (int)strlen(infix);
    char c;

    for (i = 0; i < len; i++) {
        c = infix[i];
        if (c == ' ') {
            continue;
        }
        if (isOperand(c)) {
            out[k++] = c;
            out[k++] = ' ';              /* 操作数后加空格，便于求值端分词 */
        } else if (c == '(') {
            stack[++top] = c;
        } else if (c == ')') {
            while (top != -1 && stack[top] != '(') {
                out[k++] = stack[top--];
                out[k++] = ' ';
            }
            if (top == -1) {
                out[k] = '\0';
                return 1;                /* 右括号多余 */
            }
            top--;                       /* 弹出左括号，不输出 */
        } else if (inStackPriority(c) > 0) {
            /* 栈顶优先级 >= 当前优先级的全部先弹出（左结合） */
            while (top != -1 &&
                   inStackPriority(stack[top]) >= outStackPriority(c)) {
                out[k++] = stack[top--];
                out[k++] = ' ';
            }
            stack[++top] = c;
        }
    }
    while (top != -1) {                  /* 清空栈内剩余运算符 */
        if (stack[top] == '(') {
            out[k] = '\0';
            return 1;                    /* 左括号多余 */
        }
        out[k++] = stack[top--];
        out[k++] = ' ';
    }
    out[k] = '\0';
    return 0;
}

int main(void)
{
    const char *cases[6] = {
        "1-2-3",
        "a+b*c",
        "(a+b)*c",
        "a*(b+c)/d-e",
        "10+2*6",
        "((1+2)"
    };
    char out[MAXSIZE * 2];
    int i, r;

    for (i = 0; i < 6; i++) {
        r = infixToPostfix(cases[i], out);
        if (r == 0) {
            printf("%-14s → %s\n", cases[i], out);
        } else {
            printf("%-14s → 括号失配\n", cases[i]);
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXSIZE 50

typedef struct {
    int data[MAXSIZE];
    int top;
} NumStack;

static int nsPush(NumStack *s, int x)
{
    if (s->top == MAXSIZE - 1) {
        return 1;
    }
    s->data[++s->top] = x;
    return 0;
}

static int nsPop(NumStack *s, int *x)
{
    if (s->top == -1) {
        return 1;                      /* 下溢 */
    }
    *x = s->data[s->top--];
    return 0;
}

/* 求值以空格分隔的后缀式；返回 0 成功，1 运算符缺操作数，2 结果不唯一，3 空式 */
int evalPostfix(const char *expr, int *result)
{
    NumStack s;
    char buf[256];
    char *tok;
    int a, b;

    s.top = -1;
    strcpy(buf, expr);
    tok = strtok(buf, " ");
    while (tok != NULL) {
        if (strcmp(tok, "+") == 0 || strcmp(tok, "-") == 0 ||
            strcmp(tok, "*") == 0 || strcmp(tok, "/") == 0) {
            if (nsPop(&s, &b) != 0) {
                return 1;              /* 右操作数缺失 */
            }
            if (nsPop(&s, &a) != 0) {
                return 1;              /* 左操作数缺失 */
            }
            if (tok[0] == '/' && b == 0) {
                return 1;              /* 除零，同样按非法处理 */
            }
            switch (tok[0]) {
            case '+': a = a + b; break;
            case '-': a = a - b; break;
            case '*': a = a * b; break;
            default:  a = a / b; break;
            }
            if (nsPush(&s, a) != 0) {
                return 1;
            }
        } else {
            if (nsPush(&s, atoi(tok)) != 0) {
                return 1;
            }
        }
        tok = strtok(NULL, " ");
    }
    if (s.top == -1) {
        return 3;                      /* 空表达式 */
    }
    if (s.top != 0) {
        return 2;                      /* 栈里还剩多个值：操作数多于运算符 */
    }
    *result = s.data[0];
    return 0;
}

int main(void)
{
    const char *cases[6] = {
        "1 2 - 3 -",
        "6 2 /",
        "2 6 /",
        "3 4 + 2 * 7 /",
        "1 +",
        "1 2 3 +"
    };
    int i, r, v;

    for (i = 0; i < 6; i++) {
        r = evalPostfix(cases[i], &v);
        if (r == 0) {
            printf("%-14s = %d\n", cases[i], v);
        } else {
            const char *why[4] = { "", "运算符缺少操作数或除零", "结果不唯一（操作数偏多）", "空表达式" };
            printf("%-14s 非法：%s\n", cases[i], why[r]);
        }
    }
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAXSIZE 50

typedef struct {
    int data[MAXSIZE];
    int top;
} IntStack;

typedef struct {
    char data[MAXSIZE];
    int top;
} OpStack;

/* 栈内优先级：左括号最低，任何运算符都弹不动它 */
static int inPriority(char op)
{
    switch (op) {
    case '(': return 0;
    case '+':
    case '-': return 1;
    case '*':
    case '/': return 2;
    default:  return -1;
    }
}

/* 栈外优先级：左括号最高，保证它一定能入栈 */
static int outPriority(char op)
{
    return op == '(' ? 3 : inPriority(op);
}

static int apply(int a, char op, int b)
{
    switch (op) {
    case '+': return a + b;
    case '-': return a - b;
    case '*': return a * b;
    default:  return b == 0 ? 0 : a / b;
    }
}

/* 统一的「计算一次」动作：弹一个运算符和两个操作数，结果压回操作数栈 */
static int doCalc(IntStack *num, OpStack *ops)
{
    char op;
    int a, b;

    if (ops->top == -1) {
        return 1;
    }
    op = ops->data[ops->top--];
    if (num->top < 1) {
        return 1;                      /* 操作数不足两个 */
    }
    b = num->data[num->top--];         /* 先弹出的是右操作数 */
    a = num->data[num->top--];
    num->data[++num->top] = apply(a, op, b);
    return 0;
}

/* 返回 0 成功；1 表达式非法 */
int evalInfix(const char *expr, int *result)
{
    IntStack num;
    OpStack ops;
    int i = 0, len = (int)strlen(expr), v;
    char c;

    num.top = -1;
    ops.top = -1;
    while (i < len) {
        c = expr[i];
        if (isspace((unsigned char)c)) {
            i++;
            continue;
        }
        if (isdigit((unsigned char)c)) {
            v = 0;
            while (i < len && isdigit((unsigned char)expr[i])) {
                v = v * 10 + (expr[i] - '0');   /* 多位数整体读入 */
                i++;
            }
            num.data[++num.top] = v;
            continue;
        }
        if (c == '(') {
            ops.data[++ops.top] = c;
        } else if (c == ')') {
            while (ops.top != -1 && ops.data[ops.top] != '(') {
                if (doCalc(&num, &ops) != 0) {
                    return 1;
                }
            }
            if (ops.top == -1) {
                return 1;              /* 右括号多余 */
            }
            ops.top--;                 /* 弹出左括号，不参与计算 */
        } else if (inPriority(c) > 0) {
            while (ops.top != -1 && ops.data[ops.top] != '(' &&
                   inPriority(ops.data[ops.top]) >= outPriority(c)) {
                if (doCalc(&num, &ops) != 0) {
                    return 1;
                }
            }
            ops.data[++ops.top] = c;
        } else {
            return 1;                  /* 非法字符 */
        }
        i++;
    }
    while (ops.top != -1) {            /* 清空运算符栈 */
        if (ops.data[ops.top] == '(') {
            return 1;                  /* 左括号多余 */
        }
        if (doCalc(&num, &ops) != 0) {
            return 1;
        }
    }
    if (num.top != 0) {
        return 1;                      /* 结果不唯一 */
    }
    *result = num.data[0];
    return 0;
}

int main(void)
{
    const char *cases[7] = {
        "1-2-3",
        "12+3*4",
        "(12+3)*4",
        "100/(2+3)/4",
        "2*(3+4*(5-6))",
        "10+2*6",
        "(1+2"
    };
    int i, r, v;

    for (i = 0; i < 7; i++) {
        r = evalInfix(cases[i], &v);
        if (r == 0) {
            printf("%-16s = %d\n", cases[i], v);
        } else {
            printf("%-16s 表达式非法\n", cases[i]);
        }
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

/* 递归版：每层一个活动记录，深度 n */
static int recDepthMax;

int factRec(int n, int depth)
{
    if (depth > recDepthMax) {
        recDepthMax = depth;
    }
    if (n <= 1) {
        return 1;
    }
    return n * factRec(n - 1, depth + 1);
}

/* 循环版：空间 O(1)，不产生任何栈帧 */
int factLoop(int n)
{
    int r = 1, i;

    for (i = 2; i <= n; i++) {
        r = r * i;
    }
    return r;
}

/* 显式栈模拟递归：把系统栈搬到堆上，深度只受 malloc 限制 */
typedef struct {
    int n;
    int stage;         /* 0 = 还没算子问题，1 = 子问题已返回 */
    int sub;           /* 子问题结果 */
} Frame;

int factByStack(int n)
{
    Frame *st = (Frame *)malloc((size_t)(n + 2) * sizeof(Frame));
    int top = -1, result = 1;

    if (st == NULL) {
        return -1;
    }
    st[++top].n = n;
    st[top].stage = 0;
    while (top != -1) {
        Frame *f = &st[top];
        if (f->stage == 0) {
            if (f->n <= 1) {
                f->sub = 1;            /* 递归基，直接得出本层结果 */
                f->stage = 1;
            } else {
                st[++top].n = f->n - 1;/* 递推：压入下一层 */
                st[top].stage = 0;
            }
        } else {
            result = f->sub;
            top--;                     /* 回归：弹出本层 */
            if (top != -1) {
                st[top].sub = st[top].n * result;   /* 把结果交给上一层 */
                st[top].stage = 1;
            }
        }
    }
    free(st);
    return result;
}

int main(void)
{
    int ns[4] = { 1, 4, 7, 10 };
    int recVal, loopVal, stackVal, depth;
    int i;

    printf("n  递归结果  循环结果  显式栈结果  递归最大深度\n");
    for (i = 0; i < 4; i++) {
        recDepthMax = 0;
        recVal = factRec(ns[i], 1);      /* 先调用，recDepthMax 才被更新 */
        depth = recDepthMax;             /* 再单独取，避开 printf 实参求值顺序不确定 */
        loopVal = factLoop(ns[i]);
        stackVal = factByStack(ns[i]);
        printf("n=%d 递归=%d 循环=%d 显式栈=%d 最大深度=%d\n",
               ns[i], recVal, loopVal, stackVal, depth);
    }
    printf("\n");
    printf("递归版 10! 的最大调用深度是 %d，即需要 %d 个活动记录同时在栈上\n",
           recDepthMax, recDepthMax);
    printf("循环版计算同样的值只需要 %d 个活动记录\n", 1);
    return 0;
}

#include <stdio.h>

#define MAXSIZE 5                  /* 实际可存 4 个元素 */
typedef int DataType;

typedef struct {
    DataType data[MAXSIZE];
    int front;                     /* 指向队头元素 */
    int rear;                      /* 指向队尾元素的下一个空位 */
} CircQueue;

void cqInit(CircQueue *q)
{
    q->front = 0;
    q->rear = 0;
}

int cqEmpty(const CircQueue *q)
{
    return q->front == q->rear;
}

int cqFull(const CircQueue *q)
{
    return (q->rear + 1) % MAXSIZE == q->front;    /* 牺牲一格 */
}

int cqSize(const CircQueue *q)
{
    return (q->rear - q->front + MAXSIZE) % MAXSIZE;
}

int cqEnqueue(CircQueue *q, DataType x)
{
    if (cqFull(q)) {
        return 1;                                  /* 真溢出 */
    }
    q->data[q->rear] = x;
    q->rear = (q->rear + 1) % MAXSIZE;             /* 绕环 */
    return 0;
}

int cqDequeue(CircQueue *q, DataType *x)
{
    if (cqEmpty(q)) {
        return 1;                                  /* 下溢 */
    }
    *x = q->data[q->front];
    q->front = (q->front + 1) % MAXSIZE;           /* 绕环，前部空间被释放 */
    return 0;
}

static void show(const char *tag, const CircQueue *q)
{
    printf("%s front=%d rear=%d 个数=%d 满=%d\n",
           tag, q->front, q->rear, cqSize(q), cqFull(q));
}

int main(void)
{
    CircQueue q;
    DataType x;
    int i;

    cqInit(&q);
    show("初始：", &q);

    for (i = 1; i <= 4; i++) {
        cqEnqueue(&q, i * 10);
    }
    show("入队 10 20 30 40 后：", &q);
    printf("再入队 50 返回 %d（真溢出，MAXSIZE=%d 牺牲一格只能存 4 个）\n",
           cqEnqueue(&q, 50), MAXSIZE);

    for (i = 0; i < 3; i++) {
        cqDequeue(&q, &x);
        printf("出队 %d\n", x);
    }
    show("出队 3 个后：", &q);

    /* 关键：前部 [0][1][2] 已释放，rear 绕环后能重新利用它们 */
    for (i = 1; i <= 3; i++) {
        printf("入队 %d 返回 %d\n", i * 100, cqEnqueue(&q, i * 100));
    }
    show("再入队 3 个后：", &q);

    printf("逐个出队：");
    while (cqDequeue(&q, &x) == 0) {
        printf(" %d", x);
    }
    printf("\n");
    show("清空后：", &q);
    printf("空队再出队返回 %d（下溢）\n", cqDequeue(&q, &x));
    return 0;
}

cards.content:
## 结构

```c
typedef struct QNode {
    DataType data;
    struct QNode *next;
} QNode;

typedef struct {
    QNode *front;      /* 头指针，指向头结点 */
    QNode *rear;       /* 尾指针，指向最后一个结点 */
} LinkQueue;
```

**带头结点**（`front` 指向一个不存数据的头结点，`front == rear` 表示空队）。
头结点让「空队入第一个元素」和「非空队入队」走同一套代码，不必分支。

## 入队：只改 rear

```c
p = malloc(...);  p->data = x;  p->next = NULL;
q->rear->next = p;               /* 挂到当前尾结点之后 */
q->rear = p;                     /* 尾指针后移 */
```

## 出队：唯一的陷阱在这里

```c
p = q->front->next;              /* 待删的第一个数据结点 */
if (p == NULL) return 1;         /* 空队，下溢 */
*x = p->data;
q->front->next = p->next;
if (q->rear == p) {              /* ★ 删的是最后一个结点 */
    q->rear = q->front;          /* 必须把 rear 拉回头结点 */
}
free(p);
```

**少了那个 if，队列为空时 rear 仍指向已被 free 的结点**。
下一次入队执行 `q->rear->next = p` 就是往已释放的内存里写——use-after-free，
可能当场崩溃，也可能悄悄破坏堆结构，等到很后面才炸。这是链队最经典的 bug。

## 与循环队列对比

| 维度 | 循环队列（顺序） | 链队 |
|---|---|---|
| 容量 | MAXSIZE−1（牺牲一格方案） | 只受堆限制 |
| 假溢出 | 已消除 | 不存在 |
| 每元素额外空间 | 0 | 一个 next 指针 |
| 入/出队 | O(1)，无 malloc | O(1)，含 malloc/free |
| 需要的指针 | front、rear（都是 int 下标） | front、rear（都是结点指针） |
| 特殊处理 | 取模运算 | **删到空时 rear 复位** |

容量可预估、追求极致性能时用循环队列；容量波动大、需要多个队列共存时用链队。

