#include <stdio.h>
#include <stdlib.h>

typedef struct QNode {
    int data;
    struct QNode *next;
} QNode;

typedef struct {
    QNode *front;          /* 指向头结点 */
    QNode *rear;           /* 指向最后一个结点 */
} LinkQueue;

int lqInit(LinkQueue *q)
{
    q->front = (QNode *)malloc(sizeof(QNode));
    if (q->front == NULL) {
        return 1;
    }
    q->front->next = NULL;
    q->rear = q->front;    /* 空队：front == rear */
    return 0;
}

int lqEmpty(const LinkQueue *q)
{
    return q->front == q->rear;
}

int lqEnqueue(LinkQueue *q, int x)
{
    QNode *p = (QNode *)malloc(sizeof(QNode));

    if (p == NULL) {
        return 1;
    }
    p->data = x;
    p->next = NULL;
    q->rear->next = p;     /* 挂到当前尾结点之后 */
    q->rear = p;           /* 尾指针后移 */
    return 0;
}

int lqDequeue(LinkQueue *q, int *x)
{
    QNode *p = q->front->next;

    if (p == NULL) {
        return 1;          /* 空队，下溢 */
    }
    *x = p->data;
    q->front->next = p->next;
    if (q->rear == p) {
        q->rear = q->front;/* ★ 删的是最后一个结点，rear 必须复位 */
    }
    free(p);
    return 0;
}

int lqSize(const LinkQueue *q)
{
    int n = 0;
    const QNode *p;

    for (p = q->front->next; p != NULL; p = p->next) {
        n++;
    }
    return n;
}

