        printf("\n");
        printf("第%d轮 清空后 空=%d 长度=%d rear是否等于front %d\n",
               round, lqEmpty(&q), lqSize(&q), q.rear == q.front);
    }
    printf("空队再出队返回 %d（下溢）\n", lqDequeue(&q, &x));

    /* 清空后再入队：若 rear 未复位，这一步就是 use-after-free */
    lqEnqueue(&q, 99);
    lqDequeue(&q, &x);
    printf("复位后重新入队出队得到 %d\n", x);
    free(q.front);
    return 0;
}

#include <stdio.h>

#define MAX 8
typedef int DataType;

typedef struct {
    DataType data[MAX];
    int front;                   /* 指向队头元素所在格 */
    int rear;                    /* 指向队尾元素的下一格 */
    int size;                    /* 用 size 判满，避免两端都动时公式失效 */
} Deque;

void dqInit(Deque *q)
{
    q->front = 0;
    q->rear = 0;
    q->size = 0;
}

int dqFull(const Deque *q)
{
    return q->size == MAX;
}

int dqEmpty(const Deque *q)
{
    return q->size == 0;
}

int dqInsertFront(Deque *q, DataType x)
{
    if (dqFull(q)) {
        return 1;
    }
    q->front = (q->front - 1 + MAX) % MAX;   /* 先退一格，加 MAX 防负下标 */
    q->data[q->front] = x;
    q->size++;
    return 0;
}

int dqInsertRear(Deque *q, DataType x)
{
    if (dqFull(q)) {
        return 1;
    }
    q->data[q->rear] = x;                    /* 先写，再进一格 */
    q->rear = (q->rear + 1) % MAX;
    q->size++;
    return 0;
}

int dqDeleteFront(Deque *q, DataType *x)
{
    if (dqEmpty(q)) {
        return 1;
    }
    *x = q->data[q->front];
    q->front = (q->front + 1) % MAX;
    q->size--;
    return 0;
}

int dqDeleteRear(Deque *q, DataType *x)
{
    if (dqEmpty(q)) {
        return 1;
    }
    q->rear = (q->rear - 1 + MAX) % MAX;     /* 先退一格，再读 */
    *x = q->data[q->rear];
    q->size--;
    return 0;
}

static void show(const char *tag, const Deque *q)
{
    int i, k;

    printf("%s", tag);
    for (i = 0; i < q->size; i++) {
        k = (q->front + i) % MAX;
        printf(" %d", q->data[k]);
    }
    printf("  (size=%d)\n", q->size);
}

/* 双端队列判回文：两端同时往中间删，逐个比对 */
int isPalindrome(const int *a, int n)
{
    Deque q;
    DataType l, r;
    int i;

    dqInit(&q);
    for (i = 0; i < n; i++) {
        if (dqInsertRear(&q, a[i]) != 0) {
            return -1;                 /* 数据超过容量 */
        }
    }
    while (q.size > 1) {
        dqDeleteFront(&q, &l);
        dqDeleteRear(&q, &r);
        if (l != r) {
            return 0;
        }
    }
    return 1;
}

int main(void)
{
    int p1[5] = { 1, 2, 3, 2, 1 };
    int p2[6] = { 1, 2, 3, 3, 2, 9 };
    int p3[4] = { 7, 7, 7, 7 };
    Deque q;
    DataType x;

    dqInit(&q);
    printf("insertRear 10, 20；insertFront 5, 3\n");
    dqInsertRear(&q, 10);
    dqInsertRear(&q, 20);
    dqInsertFront(&q, 5);
    dqInsertFront(&q, 3);
    show("队列:", &q);

    dqDeleteFront(&q, &x);
    printf("deleteFront → %d\n", x);
    dqDeleteRear(&q, &x);
    printf("deleteRear  → %d\n", x);
    show("剩余:", &q);

    printf("\n回文判定: 1 2 3 2 1 → %d\n", isPalindrome(p1, 5));
    printf("回文判定: 1 2 3 3 2 9 → %d\n", isPalindrome(p2, 6));
    printf("回文判定: 7 7 7 7 → %d\n", isPalindrome(p3, 4));
    return 0;
}

