## 两类递归，两种改法

| 类型 | 特征 | 改法 | 例子 |
|---|---|---|---|
| 尾递归 | `return f(...)` 是函数最后一步，返回后无需再算 | **直接改循环**，用参数当累加器 | 阶乘、斐波那契、链表遍历 |
| 非尾递归 | 返回后还要用返回值继续计算 | **显式栈模拟**，保存每层现场 | 汉诺塔、二叉树后序、归并排序 |

```c
int factTail(int n, int acc)        /* 尾递归：结果在 acc 里累积 */
{
    if (n <= 1) return acc;
    return factTail(n - 1, n * acc);
}

int factLoop(int n)                 /* 消除尾递归后就是普通循环 */
{
    int acc = 1, i;
    for (i = 2; i <= n; i++) acc *= i;
    return acc;
}
```

尾递归能改循环的原因是：递归返回后没有任何待完成的运算，当前层的现场不需要保留，
所以不必压栈。**C 标准不保证编译器做尾调用优化**，但把尾递归手动改成循环一定能省掉 O(n) 的栈空间。

## 非尾递归：显式栈模拟

`fact(n) = n * fact(n-1)` 返回后还要做一次乘法，属于非尾递归。手工模拟的通用套路：

1. 把「待处理的参数」依次压栈，直到碰到递归基；
2. 从递归基开始弹栈，用弹出的值完成当初没做完的运算。

```c
/* 压：n, n-1, ..., 2；弹：2, 3, ..., n 依次累乘 */
while (k > 1) push(s, k--);
acc = 1;
while (!empty(s)) { pop(s, &v); acc *= v; }
```

## 为什么要转

- **防爆栈**：系统栈一般 1–8 MB，递归深度上万就可能崩溃；显式栈在堆上，容量自己定。
- **可暂停可恢复**：显式栈是一个数据结构，能保存、能中断、能回溯——这是回溯法与 DFS 非递归实现的基础。
- **便于观察**：调试时能直接打印栈内容，看清算法走到哪一步。

代价是代码变长、容易在「什么时候压、什么时候弹」上出错，所以能用尾递归改循环时优先选循环。

examples.code:
#include <stdio.h>

#define MAX 32
typedef int DataType;

typedef struct {
    DataType data[MAX];
    int top;
    int peak;                    /* 记录压栈过程中出现过的最大深度 */
} Stack;

void stInit(Stack *s)
{
    s->top = -1;
    s->peak = 0;
}

int stPush(Stack *s, DataType x)
{
    if (s->top == MAX - 1) {
        return 1;                /* 上溢 */
    }
    s->data[++s->top] = x;
    if (s->top + 1 > s->peak) {
        s->peak = s->top + 1;    /* 深度 = top + 1 */
    }
    return 0;
}

int stPop(Stack *s, DataType *x)
{
    if (s->top == -1) {
        return 1;                /* 下溢 */
    }
    *x = s->data[s->top--];
    return 0;
}

/* ① 尾递归：结果在 acc 里累积，return 之后无其他运算 */
int factTail(int n, int acc)
{
    if (n <= 1) {
        return acc;              /* 递归基 */
    }
    return factTail(n - 1, n * acc);
}

/* ② 消除尾递归后的循环版：不占任何额外栈空间 */
int factLoop(int n)
{
    int acc = 1, i;

    if (n <= 1) {
        return 1;
    }
    for (i = 2; i <= n; i++) {
        acc *= i;
    }
    return acc;
}

/* ③ 显式栈模拟非尾递归：先把待乘的数压栈到递归基，再弹栈累乘 */
int factByStack(int n, int *peakDepth)
{
    Stack s;
    DataType v;
    int acc = 1, k = n;

    stInit(&s);
    while (k > 1) {              /* 压：n, n-1, ..., 2 */
        if (stPush(&s, k) != 0) {
            return -1;           /* n 太大，栈放不下 */
        }
        k--;
    }
    while (stPop(&s, &v) == 0) { /* 弹：2, 3, ..., n 依次累乘 */
        acc *= v;
    }
    *peakDepth = s.peak;
    return acc;
}

int main(void)
{
    int n, r1, r2, r3, peak;

    printf("n  尾递归  循环  显式栈  栈峰值深度\n");
    for (n = 1; n <= 6; n++) {
        peak = 0;
        r1 = factTail(n, 1);     /* ★ 先算完，再统一 printf */
        r2 = factLoop(n);
        r3 = factByStack(n, &peak);
        printf("n=%d 尾递归=%d 循环=%d 显式栈=%d 栈峰值深度=%d\n",
               n, r1, r2, r3, peak);
    }

    printf("\n说明：n=1 时递归基直接命中，显式栈一个元素都没压，峰值深度为 0\n");
    printf("n=6 时压入 6 5 4 3 2 共 5 个，峰值深度 5 = n-1\n");
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MEMO_N 32

static int naiveCalls;           /* 朴素递归的调用次数 */
static int memoCalls;            /* 记忆化中「真正展开」的次数 */
static int memo[MEMO_N];

/* ① 朴素递归：不缓存，重复计算 */
int fibNaive(int n)
{
    naiveCalls++;
    if (n <= 1) {
        return n;                /* 递归基 */
    }
    return fibNaive(n - 1) + fibNaive(n - 2);
}

/* ② 记忆化递归：命中缓存直接返回，不计入展开次数 */
int fibMemo(int n)
{
    if (n <= 1) {
        return n;
    }
    if (memo[n] >= 0) {
        return memo[n];          /* ★ 命中缓存，不再展开 */
    }
    memoCalls++;                 /* 只有真正展开才计数 */
    memo[n] = fibMemo(n - 1) + fibMemo(n - 2);
    return memo[n];
}

/* ③ 自底向上循环：只保留前两项，空间 O(1) */
int fibLoop(int n, int *iters)
{
    int a = 0, b = 1, t, i;

    *iters = 0;
    if (n <= 0) {
        return 0;
    }
    for (i = 2; i <= n; i++) {
        t = a + b;
        a = b;
        b = t;
        (*iters)++;
    }
    return (n == 1) ? 1 : b;
}

int main(void)
{
    int ns[4] = { 5, 10, 15, 20 };
    int i, f1, f2, f3, iters, same;

    printf("n  fib(n)  三法一致  朴素递归调用次数  记忆化展开次数  循环迭代次数\n");
    for (i = 0; i < 4; i++) {
        naiveCalls = 0;
        memoCalls = 0;
        memset(memo, -1, sizeof(memo));   /* ★ 用 -1 表示「未算过」，不能用 0 */

        f1 = fibNaive(ns[i]);
        f2 = fibMemo(ns[i]);
        f3 = fibLoop(ns[i], &iters);
        same = (f1 == f2 && f2 == f3) ? 1 : 0;   /* 三法结果必须相同 */
        printf("n=%d fib=%d 三法一致=%d 朴素递归=%d 记忆化=%d 循环=%d\n",
               ns[i], f1, same, naiveCalls, memoCalls, iters);
    }

    printf("\n三列 fib 值必须完全一致，否则实现有错\n");
    printf("朴素递归次数满足 T(n)=2*fib(n+1)-1：n=20 时 2*10946-1=21891\n");
    return 0;
}

#include <stdio.h>

#define MAXN 8

static int n;
static int path[MAXN];           /* 当前已选的数字序列 */
static int used[MAXN];           /* used[i]=1 表示数字 i+1 已被占用 */
static int chooseCount;          /* 做选择次数 */
static int unchooseCount;        /* 撤销选择次数 */
static int solutionCount;        /* 找到的解个数 */

static void printPath(void)
{
    int i;

    solutionCount++;
    printf("解%d:", solutionCount);
    for (i = 0; i < n; i++) {
        printf(" %d", path[i]);
    }
    printf("\n");
}

/* 正确版：做选择 → 递归 → 撤销选择 */
void permute(int depth)
{
    int i;

    if (depth == n) {            /* 递归基：n 个位置都填好了 */
        printPath();
        return;
    }
    for (i = 1; i <= n; i++) {
        if (used[i]) {
            continue;            /* 剪枝：该数字已用过 */
        }
        path[depth] = i;         /* 做选择 */
        used[i] = 1;
        chooseCount++;

        permute(depth + 1);      /* 深入下一层 */

        used[i] = 0;             /* ★ 撤销选择，恢复现场 */
        unchooseCount++;
    }
}

/* 错误版：忘记撤销，用于对比解的数量 */
static int badCount;
static int badUsed[MAXN];
static int badPath[MAXN];

void permuteNoUndo(int depth)
{
    int i;

    if (depth == n) {
        badCount++;
        return;
    }
    for (i = 1; i <= n; i++) {
        if (badUsed[i]) {
            continue;
        }
        badPath[depth] = i;
        badUsed[i] = 1;          /* 做了选择 */
        permuteNoUndo(depth + 1);
        /* ★ 这里漏了 badUsed[i] = 0 */
    }
}

int main(void)
{
    int i;

    n = 3;
    for (i = 0; i <= n; i++) {
        used[i] = 0;
        badUsed[i] = 0;
    }
    chooseCount = 0;
    unchooseCount = 0;
    solutionCount = 0;
    badCount = 0;

    printf("n=%d 的全部排列（正确回溯，含撤销）:\n", n);
    permute(0);
    printf("选择次数=%d 撤销次数=%d 解个数=%d（应为 %d! = 6）\n",
           chooseCount, unchooseCount, solutionCount, n);

    printf("\n同样的搜索但漏写撤销:\n");
    permuteNoUndo(0);
    printf("解个数=%d —— 少了 %d 个，因为 used 标记被上一层污染\n",
           badCount, solutionCount - badCount);
    return 0;
}

#include <stdio.h>

static int moveCount;

/* 把 n 个盘从 from 借助 aux 移到 to */
void hanoi(int n, char from, char to, char aux)
{
    if (n <= 0) {
        return;                  /* 递归基 */
    }
    hanoi(n - 1, from, aux, to); /* ① 上面 n-1 个盘挪到辅助柱 */
    moveCount++;
    printf("  %c->%c\n", from, to);/* ② 最大盘直接到目标柱 */
    hanoi(n - 1, aux, to, from); /* ③ n-1 个盘再挪到目标柱 */
}

#define MAXN 32

static int tmp[MAXN];

/* 合并 [left..mid] 与 [mid+1..right] 两个有序段 */
void merge(int *a, int left, int mid, int right)
{
    int i = left, j = mid + 1, k = left;

    while (i <= mid && j <= right) {
        if (a[i] <= a[j]) {      /* ★ <= 保证稳定性：相等时先取左段 */
            tmp[k++] = a[i++];
        } else {
            tmp[k++] = a[j++];
        }
    }
    while (i <= mid) {           /* 左段剩余 */
        tmp[k++] = a[i++];
    }
    while (j <= right) {         /* 右段剩余 */
        tmp[k++] = a[j++];
    }
    for (i = left; i <= right; i++) {
        a[i] = tmp[i];           /* 写回原数组 */
    }
}

void mergeSort(int *a, int left, int right)
{
    int mid;

    if (left >= right) {         /* 递归基：只剩 0 或 1 个元素 */
        return;
    }
    mid = (left + right) / 2;
    mergeSort(a, left, mid);
    mergeSort(a, mid + 1, right);
    merge(a, left, mid, right);
}

int main(void)
{
    int a[7] = { 5, 2, 8, 1, 9, 3, 7 };
    int i;

    printf("汉诺塔 n=3（A 借助 B 移到 C）:\n");
    moveCount = 0;
    hanoi(3, 'A', 'C', 'B');
    printf("移动次数=%d（2^3-1=7）\n", moveCount);

    printf("\n各 n 的移动次数:\n");
    for (i = 1; i <= 5; i++) {
        /* 不打印过程，只算次数：2^i - 1 */
        printf("n=%d 次数=%d\n", i, (1 << i) - 1);
    }

    printf("\n归并排序:\n  原数组:");
    for (i = 0; i < 7; i++) {
        printf(" %d", a[i]);
    }
    mergeSort(a, 0, 6);
    printf("\n  排序后:");
    for (i = 0; i < 7; i++) {
        printf(" %d", a[i]);
    }
    printf("\n");
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAX 64
typedef int DataType;

typedef struct {
    DataType data[MAX];
    int top;
} Stack;

void stInit(Stack *s)
{
    s->top = -1;
}

int stPush(Stack *s, DataType x)
{
    if (s->top == MAX - 1) {
        return 1;
    }
    s->data[++s->top] = x;
    return 0;
}

int stPop(Stack *s, DataType *x)
{
    if (s->top == -1) {
        return 1;
    }
    *x = s->data[s->top--];
    return 0;
}

int stEmpty(const Stack *s)
{
    return s->top == -1;
}

static const char DIGITS[] = "0123456789ABCDEF";

/* 十进制 n 转 R 进制并打印；余数入栈 → 全部出栈即为逆序还原 */
void convert(int n, int r)
{
    Stack s;
    DataType d;

    stInit(&s);
    printf("%d 的 %d 进制 = ", n, r);
    if (n == 0) {                /* ★ 特例：0 在任何进制下都是 "0" */
        printf("0\n");
        return;
    }
    while (n > 0) {
        if (stPush(&s, n % r) != 0) {
            printf("[栈溢出]\n");
            return;
        }
        n /= r;
    }
    while (stPop(&s, &d) == 0) {
        printf("%c", DIGITS[d]); /* 出栈次序正好是高位到低位 */
    }
    printf("\n");
}

/* 栈式回文判定：前半段压栈，后半段逐个与弹栈值比对 */
int isPalindrome(const char *str)
{
    Stack s;
    DataType d;
    int len = (int)strlen(str);
    int half = len / 2;
    int i, j;

    stInit(&s);
    for (i = 0; i < half; i++) {
        stPush(&s, str[i]);
    }
    j = (len % 2 == 1) ? half + 1 : half;   /* ★ 奇数长度跳过正中间 */
    for (; j < len; j++) {
        if (stPop(&s, &d) != 0) {
            return 0;
        }
        if ((char)d != str[j]) {
            return 0;
        }
    }
    return stEmpty(&s);
}

int main(void)
{
    const char *words[4] = { "level", "abc", "12321", "abca" };
    int i;

    printf("== 数制转换（除基取余 + 栈逆序输出）==\n");
    convert(1348, 8);
    convert(255, 16);
    convert(13, 2);
    convert(0, 8);

    printf("\n== 回文判定 ==\n");
    for (i = 0; i < 4; i++) {
        printf("%s → %d\n", words[i], isPalindrome(words[i]));
    }
    return 0;
}
